const errItem = $input.first()?.json || {};

// Strictly sanitize: Never leak API keys, auth headers, client IPs or raw image bytes
return [{
  json: {
    timestamp: new Date().toISOString(),
    workflowName: errItem.workflow?.name || 'Tsukuyomi Workflow',
    executionId: errItem.execution?.id || 'unknown',
    status: 'failed',
    sanitizedMessage: errItem.execution?.error?.message || 'Upstream provider failure occurred. Fallback engaged.'
  }
}];
